#!/usr/bin/env bash
# Print the three most frequent IP addresses in access.log, one per line,
# most frequent first; break ties by first appearance in the log.
set -euo pipefail
cd "$(dirname "$0")"

awk '
{
    for (f = 1; f <= NF; f++) {
        if ($f ~ /^([0-9]{1,3}\.){3}[0-9]{1,3}$/) {
            ip = $f
            count[ip]++
            if (!(ip in first_seen)) {
                first_seen[ip] = NR
            }
            break
        }
    }
}
END {
    n = asorti(count, ips, "@val_num_asc")
    # We want most frequent first, ties broken by first appearance (ascending NR).
    # Build a sortable key per ip: (count desc, first_seen asc) -> sortable string.
    for (i = 1; i <= n; i++) {
        ip = ips[i]
        # Pad to fixed width so string sort works: count desc -> 999999999 - count
        key = sprintf("%09d %09d %s", 999999999 - count[ip], first_seen[ip], ip)
        keys[i] = key
    }
    m = asort(keys, sorted)
    for (i = 1; i <= m && i <= 3; i++) {
        split(sorted[i], parts, " ")
        print parts[3]
    }
}
' access.log

#!/usr/bin/env bash
# Print the three most frequent IP addresses in access.log, one per line,
# most frequent first; break ties by first appearance in the log.
set -euo pipefail
cd "$(dirname "$0")"

awk '
{
    for (f = 1; f <= NF; f++) {
        if ($f ~ /^([0-9]{1,3}\.){3}[0-9]{1,3}$/) {
            ip = $f
            count[ip]++
            if (!(ip in first_seen)) {
                first_seen[ip] = NR
            }
            break
        }
    }
}
END {
    # Collect unique IPs preserving first-appearance order.
    n = 0
    for (ip in count) {
        n++
        order[n] = ip
    }

    # Pick top 3: highest count, tie -> smallest first_seen (earliest line).
    for (t = 1; t <= 3 && t <= n; t++) {
        best = ""
        for (i = 1; i <= n; i++) {
            ip = order[i]
            if (ip in picked) continue
            if (best == "") {
                best = ip
                continue
            }
            if (count[ip] > count[best] ||
                (count[ip] == count[best] && first_seen[ip] < first_seen[best])) {
                best = ip
            }
        }
        if (best == "") break
        picked[best] = 1
        print best
    }
}
' access.log

